var ks=Object.keys(W).filter(function(k){return RND[act].react[k]&&lines(X,RND[act].react[k].T,a,b).length;});
return wpick(X.rng,ks,function(k){return W[k];})||ks[0]||Object.keys(RND[act].react)[0];
