function pickPair(X,a,b,notSys,prefA){
var C=cands(X,a,b),by={rel:[],emo:[],per:[],rnd:[]};
C.list.forEach(function(c){if(c.sys!==notSys&&(!prefA||c.a===prefA))by[c.sys].push(c);});
if(prefA&& !by.rel.length&& !by.emo.length&& !by.per.length&& !by.rnd.length)C.list.forEach(function(c){if(c.sys!==notSys)by[c.sys].push(c);});
var SW=C.stranger?{per:1,rnd:1}:{rel:2.4,emo:1,per:0.8,rnd:0.8};
var sys=wpick(X.rng,Object.keys(SW).filter(function(k){return by[k].length;}),function(k){return SW[k];});
if(!sys)return null;
return wpick(X.rng,by[sys],function(c){return c.w;});
}
function plan(X){
var P=X.people,out=[];
if(P.length===2){
var c1=pickPair(X,P[0],P[1]);
if(c1)out.push(c1);
if(c1&&X.rng()<0.35){var c2=pickPair(X,P[0],P[1],c1.sys,c1.b);if(c2)out.push(c2);}
return out;
}
var pairs=[];
(X.groups||[P]).forEach(function(G){for(var i=0;i<G.length;i++)for(var j=i+1;j<G.length;j++)pairs.push([G[i],G[j]]);});
if(pairs.length){
var tied=pairs.filter(function(q){return tieList(X,q[0],q[1]).some(function(t){return t.type!=='noobs';});});
var first=tied.length&&X.rng()<0.8?tied[X.rng.int(tied.length)]:pairs[X.rng.int(pairs.length)];
var e1=pickPair(X,first[0],first[1]);
if(e1)out.push(e1);
var rest=pairs.filter(function(q){return q!==first&&q.indexOf(first[0])<0&&q.indexOf(first[1])<0;});
if(!rest.length)rest=pairs.filter(function(q){return q!==first;});
if(rest.length&&X.rng()<(P.length>=4?0.6:0.35)){
var rt=rest.filter(function(q){return tied.indexOf(q)>=0;}),sec=rt.length&&X.rng()<0.7?rt[X.rng.int(rt.length)]:rest[X.rng.int(rest.length)];
var e2=pickPair(X,sec[0],sec[1],e1&&e1.sys);
if(e2)out.push(e2);
}
}
out.push({sys:'group'});
return out;
}
